(()=>{
let cart=[];try{cart=JSON.parse(sessionStorage.getItem('hoc-quote-draft')||'[]')}catch{}if(!Array.isArray(cart))cart=[];
const dialog=document.createElement('dialog');dialog.className='quote-dialog';dialog.innerHTML=`<button class="close" aria-label="Close quote request">×</button><p class="kicker">LET'S TALK ABOUT YOUR BUILD</p><h2>GET A QUOTE.</h2><div id="quote-items"></div><pre class="quote-summary" hidden></pre><form><div class="quote-row"><div><label for="quote-name">Your name</label><input id="quote-name" name="name" autocomplete="name" required maxlength="100"></div><div><label for="quote-email">Email</label><input id="quote-email" name="email" type="email" autocomplete="email" required maxlength="200"></div></div><label for="quote-vehicle">Your vehicle</label><input id="quote-vehicle" name="vehicle" required placeholder="e.g. 2018 Volkswagen Golf R" maxlength="200"><label for="quote-install">What do you need?</label><select id="quote-install" name="service"><option>Parts + installation</option><option>Parts only</option><option>Vinyl wrap</option><option>Mechanical work</option><option>Full custom build</option></select><label for="quote-notes">Tell us about your project</label><textarea id="quote-notes" name="notes" maxlength="3000" placeholder="Your ideas, preferred finish, parts or timeline…"></textarea><p class="quote-notice">Online submission is not connected yet. You can download your request with your selected parts and build details. Nothing is sent automatically.</p><button class="cta" type="submit">Download quote request ↓</button><p id="quote-feedback" role="status"></p></form>`;document.body.append(dialog);
const save=()=>{try{sessionStorage.setItem('hoc-quote-draft',JSON.stringify(cart))}catch{}document.querySelectorAll('#cart-count').forEach(x=>x.textContent=cart.length);window.dispatchEvent(new Event('hoc-cart-change'))};
function list(){const target=dialog.querySelector('#quote-items');target.replaceChildren();cart.forEach((item,i)=>{const row=document.createElement('div');row.className='cart-row';const label=document.createElement('span');label.textContent=item.name+' · '+item.vehicle;const btn=document.createElement('button');btn.textContent='Remove';btn.onclick=()=>{cart.splice(i,1);save();list()};row.append(label,btn);target.append(row)})}
function buildSummary(){if(typeof state==='undefined')return '';const s=state;return `${document.body.dataset.model}\nWrap: ${s.paint}\nWheels: ${document.querySelector('.wheel.selected')?.title||s.wheel}\nSteering wheel: ${s.steering}\nFront lip: ${document.querySelector('#front-lip')?.selectedOptions[0].text}\nRear diffuser: ${document.querySelector('#rear-diffuser')?.selectedOptions[0].text}\nExhaust: ${document.querySelector('#exhaust-style')?.selectedOptions[0].text}`}
function open(service){list();const summary=dialog.querySelector('.quote-summary');summary.textContent=buildSummary();summary.hidden=!summary.textContent;dialog.querySelector('#quote-vehicle').value=document.body.dataset.model||'';if(['Mechanical work','Vinyl wrap','Parts installation'].includes(service))dialog.querySelector('#quote-install').value=service==='Parts installation'?'Parts + installation':service;dialog.querySelector('#quote-feedback').textContent='';dialog.showModal()}
document.addEventListener('click',e=>{const button=e.target.closest('[data-quote]');if(button)open(button.dataset.quote)});dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()}});
dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const text=['HOC — QUOTE REQUEST DRAFT','Not submitted to HOC.','',...Array.from(f,([k,v])=>k.toUpperCase()+': '+v),'',buildSummary(),'',...cart.map(x=>'PART: '+x.name+' | '+x.vehicle),'','Pricing and fitment to be confirmed.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='HOC-quote-request.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);dialog.querySelector('#quote-feedback').textContent='Request downloaded. It has not been submitted.'};
window.hocQuote={add(item){if(!cart.some(x=>x.id===item.id))cart.push(item);save()},has(id){return cart.some(x=>x.id===id)},open};save();
})();
